const agent = require('./agents/default');

let runtime;

function generateSuggestion(node, flow) {
    const suggestion = agent.generateSuggestion(node, flow);
    // todo: clean out overlap from the suggestion with what we already have in our flow
    console.log("Suggestion:", suggestion);
    return suggestion;
}

module.exports = {
    init: function(_runtime) {
        runtime = _runtime;
        console.log("Autocomplete initialized");

        // when a node is added, create a suggestion
        runtime.events.on('comms:message:nodes/add', function(msg) {
            const node = msg.data;
            if (!node.z) {
                return; // is a config node
            }
            const flow = runtime.flows.getFlow(node.z);

            // create suggestion given the new node, and existing flow
            const suggestion = generateSuggestion(runtime, node, flow);
            // todo: clean out overlap from the suggestion with what we already have in our flow
            runtime.events.emit('comms', {
                topic: "autocomplete/suggestion",
                data: suggestion
            })
        })   
    }
}